import { photoSize } from './photo.js';
const escape = value => String(value || '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
export function imagePage({ user, data, busy, progress, error, saved }) {
  if (user?.role !== 'admin') return '<p class="page-lead">只有管理员可以管理图片空间。</p>';
  const pending = data?.items.filter(item => !item.optimized).length || 0;
  return `<div class="section-head"><h1 class="page-title">图片空间</h1><button class="button ghost" data-action="reload-images" ${busy ? 'disabled' : ''}>刷新统计</button></div><p class="page-lead">把空间留给更多好味道。新照片会自动压缩，已有照片可在这里统一优化。</p><div class="image-metrics"><section class="panel"><p>图片总数</p><strong>${data ? data.items.length : '—'}</strong><small>包含历史版本使用的图片</small></section><section class="panel"><p>图片占用</p><strong>${data ? photoSize(data.bytes) : '—'}</strong><small>图片对象大小，不含其他数据</small></section><section class="panel"><p>待优化</p><strong>${data ? pending : '—'}</strong><small>已处理的图片自动跳过</small></section></div><section class="panel"><h2>批量优化已有图片</h2><p>自动选择更小的图片格式，并调整画质与尺寸。完成校验后释放旧图片文件，菜谱和历史版本的图片引用保持有效。</p><p class="small-note">优化以每张约 80 KB 为目标。已有小图片不会被放大。处理期间请保持页面打开，可随时停止，之后继续。</p><div class="management-actions"><button class="button primary" data-action="optimize-images" ${busy || !pending ? 'disabled' : ''}>优化 ${pending} 张图片</button>${busy && data ? '<button class="button ghost" data-action="stop-images">停止处理</button>' : ''}</div>${progress ? `<p class="image-progress" role="status" aria-live="polite">${escape(progress)}</p>` : ''}${saved ? `<p class="small-note">本次累计释放 ${photoSize(saved)}</p>` : ''}${error ? `<p class="form-error" role="alert">${escape(error)}</p>` : ''}</section>`;
}
